package com.shikshasetu.controller;
import com.shikshasetu.model.*;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import com.shikshasetu.service.PortalAuditService;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import java.security.SecureRandom;import java.util.*;
@RestController @RequestMapping("/api/super-admin") public class SuperAdminController{
 private final InstitutionRepository institutions;private final PortalUserRepository users;private final PortalSessionRepository sessions;private final PortalAuditService audit;private static final SecureRandom RANDOM=new SecureRandom();
 public SuperAdminController(InstitutionRepository i,PortalUserRepository u,PortalSessionRepository s,PortalAuditService a){institutions=i;users=u;sessions=s;audit=a;}
 public record CreateInstitutionRequest(@NotBlank @Size(max=160) String institutionName,@NotBlank @Size(max=120) String adminName,@Email @NotBlank @Size(max=180) String adminEmail,@NotBlank @Size(min=10,max=128) String temporaryPassword){}
 @GetMapping("/institutions") public List<Map<String,Object>> list(){return institutions.findAllByOrderByNameAsc().stream().map(i->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.getId());m.put("name",i.getName());m.put("accessCode",i.getAccessCode());m.put("active",i.isActive());m.put("createdAt",i.getCreatedAt());m.put("admins",users.findByInstitutionIdOrderByCreatedAtDesc(i.getId()).stream().filter(u->"INSTITUTION_ADMIN".equals(u.getRole())).count());m.put("students",users.countByInstitutionIdAndAccountStatusAndRole(i.getId(),"ACTIVE","STUDENT"));m.put("pending",users.countByInstitutionIdAndAccountStatus(i.getId(),"PENDING"));return m;}).toList();}
 @PostMapping("/institutions") @Transactional public Map<String,Object> create(@Valid @RequestBody CreateInstitutionRequest r){String email=r.adminEmail().trim().toLowerCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Admin email is already registered");Institution i=new Institution();i.setName(r.institutionName().trim());i.setAccessCode(generateCode());i.setCreatedByUserId(PortalAuthContext.require().userId());institutions.save(i);PortalUser a=new PortalUser();a.setEmail(email);a.setFullName(r.adminName().trim());a.setPasswordHash(PortalPasswordHasher.hash(r.temporaryPassword()));a.setRole("INSTITUTION_ADMIN");a.setAccountStatus("ACTIVE");a.setInstitutionId(i.getId());a.setChatMonitoringConsent(false);users.save(a);audit.recordFor(i.getId(),PortalAuthContext.require().userId(),"INSTITUTION_CREATED",a.getId(),"Institution workspace and first administrator provisioned");return Map.of("institutionId",i.getId(),"institutionName",i.getName(),"institutionCode",i.getAccessCode(),"adminEmail",a.getEmail(),"message","Share the institution code with enrolled students. Deliver the admin's temporary password through a secure channel.");}
 @PatchMapping("/institutions/{id}/status") @Transactional public Map<String,Object> status(@PathVariable Long id,@RequestBody Map<String,Boolean> body){Institution i=institutions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Institution not found"));i.setActive(Boolean.TRUE.equals(body.get("active")));institutions.save(i);if(!i.isActive()){for(PortalUser user:users.findByInstitutionIdOrderByCreatedAtDesc(id)){List<PortalSession> active=sessions.findByUserIdAndRevokedAtIsNull(user.getId());active.forEach(PortalSession::revoke);sessions.saveAll(active);}}audit.record("INSTITUTION_STATUS_CHANGED",id,"active="+i.isActive());return Map.of("id",id,"active",i.isActive());}
 private static String generateCode(){byte[] b=new byte[6];RANDOM.nextBytes(b);return "SS-"+Base64.getUrlEncoder().withoutPadding().encodeToString(b).replace('-','X').replace('_','Y').toUpperCase(Locale.ROOT).substring(0,8);}
}
